"""Embeds TrueType fonts as C byte arrays for the portable text engine.

    python gpu/extern/gen_font_header.py Inter_18pt-Regular.ttf Inter_18pt-Bold.ttf

(from the repo's inter.zip, static/)

writes gpu/extern/font_inter.h (g_font_inter_regular / g_font_inter_bold).
Inter (https://rsms.me/inter, SIL Open Font License 1.1, see
gpu/extern/Inter-LICENSE.txt) is the UI font Blender ships.
"""

import sys
from pathlib import Path

OUT = Path(__file__).resolve().parent / "font_inter.h"
NAMES = ["g_font_inter_regular", "g_font_inter_bold"]


def array(name: str, data: bytes) -> str:
    rows = []
    for i in range(0, len(data), 40):
        rows.append(",".join(str(b) for b in data[i : i + 40]))
    body = ",\n".join(rows)
    return f"static const unsigned char {name}[{len(data)}] = {{\n{body}}};\n"


def main() -> None:
    parts = [
        "/* Generated by gpu/extern/gen_font_header.py. Do not edit.\n"
        " * Inter (static 18pt cut, Google Fonts), Copyright 2020 The Inter Project Authors\n"
        " * (https://github.com/rsms/inter), SIL Open Font License 1.1:\n"
        " * see Inter-LICENSE.txt next to this file. */\n"
        "#pragma once\n"
    ]
    for name, path in zip(NAMES, sys.argv[1:3]):
        parts.append(array(name, Path(path).read_bytes()))
    OUT.write_text("\n".join(parts), encoding="ascii", newline="\n")
    print(f"wrote {OUT} ({OUT.stat().st_size / 1e6:.1f} MB)")


if __name__ == "__main__":
    main()
